// aegis/data/hafez.json + data/tarot.json → tgcloud/lib/data/fal.js, and data/quran.json + data/khayyam.json +
// data/babataher.json → tgcloud/lib/data/fal2.js (deployed modules can't read files, so the data is compiled into modules).
// Texts are stored deflated and base64-encoded; the bot inflates a part when it needs it
// (lib/engines/fun.js, sections fal and faith).
//   node scripts/build-fal.mjs           write
//   node scripts/build-fal.mjs --check   fail if the generated file is stale
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import zlib from 'node:zlib';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'tgcloud/lib/data/fal.js');
const PER = 50;
const check = process.argv.includes('--check');

const hafez = JSON.parse(fs.readFileSync(path.join(ROOT, 'data/hafez.json'), 'utf8')).ghazals;
const tarot = JSON.parse(fs.readFileSync(path.join(ROOT, 'data/tarot.json'), 'utf8')).cards;
const problems = [];
if (hafez.length !== 495) problems.push(`${hafez.length} ghazals, expected 495`);
hafez.forEach((g, i) => {
  if (g.n !== i + 1) problems.push(`ghazal ${i + 1} is numbered ${g.n}`);
  if (!Array.isArray(g.v) || g.v.length < 3 || g.v.some((b) => !Array.isArray(b) || b.length !== 2 || b.some((m) => typeof m !== 'string' || !m.trim()))) {
    problems.push(`ghazal ${g.n}: verses must be pairs of non-empty lines`);
  }
  if (typeof g.f !== 'string' || g.f.length < 60) problems.push(`ghazal ${g.n}: interpretation missing or too short`);
  if (/[<>&‎‏]/.test(JSON.stringify(g))) problems.push(`ghazal ${g.n}: no < > & or direction marks (the text goes into Telegram HTML)`);
});
if (tarot.length !== 78 || tarot.some((c) => !/^https:\/\/[^\s"']+\.(jpe?g|png)$/i.test(c.img))) problems.push('tarot: 78 https image URLs');
if (problems.length) {
  for (const p of problems) console.error(`✘ ${p}`);
  process.exit(1);
}

const chunks = [];
for (let i = 0; i < hafez.length; i += PER) {
  const part = hafez.slice(i, i + PER).map((g) => ({ v: g.v, f: g.f }));
  chunks.push(zlib.deflateRawSync(Buffer.from(JSON.stringify(part), 'utf8'), { level: 9 }).toString('base64'));
}
const src = `/*
 * Generated by scripts/build-fal.mjs from data/hafez.json and data/tarot.json — do not edit by hand.
 * HAFEZ: the Divan of Hafez, the 495 ghazals (public domain; text as published on ganjoor.net) with an
 * interpretation of each written for Aegis — ${PER} ghazals per chunk, each chunk raw-DEFLATE then base64:
 * a JSON array of { v: [[line 1, line 2], …], f: interpretation }.
 * TAROT_IMG: the 78 Rider–Waite–Smith cards (1909, public domain) on Wikimedia Commons, in card order.
 */
export const HAFEZ_COUNT = ${hafez.length};
export const HAFEZ_PER = ${PER};
export const HAFEZ = [
${chunks.map((c) => `  '${c}',`).join('\n')}
];
export const TAROT_IMG = [
${tarot.map((c) => `  '${c.img}',`).join('\n')}
];
`;
/* fal2.js: the first verse of each page of the Quran, for istikhara */
const quran = JSON.parse(fs.readFileSync(path.join(ROOT, 'data/quran.json'), 'utf8'));
if (quran.pages.length !== 604 || quran.pages.some((p) => p.length !== 3 || !(p[0] >= 1 && p[0] <= 114) || !(p[1] >= 1) || typeof p[2] !== 'string' || !p[2].trim()
  || /[<>&\uFEFF]/.test(p[2]))) problems.push('quran: 604 pages of [surah, ayah, text], no < > & or BOM');
for (const k of ['surah_ar', 'surah_en', 'surah_fa']) if (!Array.isArray(quran[k]) || quran[k].length !== 114) problems.push(`quran: ${k} must name the 114 surahs`);
if (problems.length) {
  for (const p of problems) console.error(`✘ ${p}`);
  process.exit(1);
}
/* poetry readings: Khayyam's quatrains and Baba Taher's dobeytis, each with its interpretation */
const POEMS_PER = 60;
const books = {};
for (const [name, count] of [['khayyam', 178], ['babataher', 366]]) {
  const poems = JSON.parse(fs.readFileSync(path.join(ROOT, `data/${name}.json`), 'utf8')).poems;
  if (poems.length !== count) problems.push(`${name}: ${poems.length} poems, expected ${count}`);
  poems.forEach((p, i) => {
    if (p.n !== i + 1) problems.push(`${name} ${i + 1} is numbered ${p.n}`);
    if (!Array.isArray(p.v) || p.v.length !== 2 || p.v.some((b) => !Array.isArray(b) || b.length !== 2 || b.some((m) => typeof m !== 'string' || !m.trim()))) {
      problems.push(`${name} ${p.n}: two verses of two non-empty lines`);
    }
    if (typeof p.f !== 'string' || p.f.length < 40) problems.push(`${name} ${p.n}: interpretation missing or too short`);
    if (/[<>&\u200B\u200E\u200F\u202A-\u202E\u2066-\u2069\uFEFF]/.test(JSON.stringify(p))) problems.push(`${name} ${p.n}: no < > & or direction marks`);
  });
  books[name] = poems;
}
if (problems.length) {
  for (const p of problems) console.error(`✘ ${p}`);
  process.exit(1);
}
const pack = (value) => zlib.deflateRawSync(Buffer.from(JSON.stringify(value), 'utf8'), { level: 9 }).toString('base64');
const packPoems = (poems) => {
  const out = [];
  for (let i = 0; i < poems.length; i += POEMS_PER) out.push(pack(poems.slice(i, i + POEMS_PER).map((p) => ({ v: p.v, f: p.f }))));
  return out;
};
const chunkList = (name, values) => `export const ${name} = [\n${values.map((v) => `  '${v}',`).join('\n')}\n];\n`;
const list = (name, values) => `export const ${name} = [\n${values.map((v) => `  ${JSON.stringify(v)},`).join('\n')}\n];\n`;
const src2 = `/*
 * Generated by scripts/build-fal.mjs from data/quran.json — do not edit by hand.
 * QURAN: the first verse on each of the 604 pages of the Medina mushaf, [surah, ayah, text], raw-DEFLATE then
 * base64 of the JSON array. Quran text: Tanzil Project (tanzil.net), Uthmani script, copied verbatim.
 * SURAH_AR / SURAH_EN: the surah names in Arabic and transliterated (same source); SURAH_FA: Persian names.
 * KHAYYAM / BABATAHER (from data/khayyam.json, data/babataher.json): the 178 quatrains of Khayyam and the 366
 * dobeytis of Baba Taher (public domain; text as published on ganjoor.net) with an interpretation of each
 * written for Aegis — ${POEMS_PER} poems per chunk, each chunk raw-DEFLATE then base64 of a JSON array of
 * { v: [[line 1, line 2], [line 3, line 4]], f: interpretation }.
 */
export const QURAN = '${pack(quran.pages)}';
${list('SURAH_AR', quran.surah_ar)}${list('SURAH_EN', quran.surah_en)}${list('SURAH_FA', quran.surah_fa)}export const POEMS_PER = ${POEMS_PER};
export const KHAYYAM_COUNT = ${books.khayyam.length};
export const BABATAHER_COUNT = ${books.babataher.length};
${chunkList('KHAYYAM', packPoems(books.khayyam))}${chunkList('BABATAHER', packPoems(books.babataher))}`;
const OUT2 = path.join(ROOT, 'tgcloud/lib/data/fal2.js');
const before2 = fs.existsSync(OUT2) ? fs.readFileSync(OUT2, 'utf8') : '';
if (before2 !== src2) {
  if (check) {
    console.error('✘ tgcloud/lib/data/fal2.js is out of date: run node scripts/build-fal.mjs');
    process.exit(1);
  }
  fs.writeFileSync(OUT2, src2);
}
const before = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
if (before !== src) {
  if (check) {
    console.error('✘ tgcloud/lib/data/fal.js is out of date: run node scripts/build-fal.mjs');
    process.exit(1);
  }
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(OUT, src);
}
console.log(`✔ fal data: ${hafez.length} ghazals in ${chunks.length} chunks (${Math.round(src.length / 1024)} KB), ${tarot.length} tarot cards; ${quran.pages.length} Quran pages, ${books.khayyam.length} + ${books.babataher.length} poems (fal2.js ${Math.round(src2.length / 1024)} KB)${check ? ' (up to date)' : ''}`);
